export const contentFactory = (type, token) => {
  const API_BASE = "http://127.0.0.1:8000/api";

  const generateSlug = (text) => {
    return (
      text
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "") +
      "-" +
      Date.now()
    );
  };

  switch (type) {
    case "article":
      return async (articleData) => {
        const formData = new FormData();
        const slug =
          articleData.slug && articleData.slug.trim() !== ""
            ? generateSlug(articleData.slug)
            : generateSlug(articleData.title || "article");

        formData.append("slug", slug);

        // Додаємо інші поля
        Object.entries(articleData).forEach(([key, value]) => {
          if (value !== undefined && value !== null) {
            if (key === "is_premium") {
              formData.append(key, value ? "true" : "false"); // ✅ булеве поле
            } else {
              formData.append(key, value);
            }
          }
        });

        // Додаємо автора, якщо він обраний
        if (articleData.author) {
          formData.append("author", articleData.author);
        }

        const res = await fetch(`${API_BASE}/articles/`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: formData,
        });

        if (!res.ok) {
          const errData = await res.json();
          console.error("📛 Помилка створення статті:", errData);
          throw new Error("Не вдалося створити статтю");
        }

        return await res.json();
      };

    case "poll":
      return async (pollData) => {
        // 1️⃣ Створюємо статтю типу interactive
        const articleForm = new FormData();
        const slug = generateSlug(pollData.question || "poll");

        articleForm.append("title", pollData.question || "Опитування");
        articleForm.append("slug", slug);
        articleForm.append("content", "");
        articleForm.append("excerpt", "");
        articleForm.append("status", "published");
        articleForm.append("type", "interactive");
        articleForm.append("category", "News");
        articleForm.append("is_premium", pollData.is_premium ? "true" : "false");

        if (pollData.channel) articleForm.append("channel", pollData.channel);
        if (pollData.author) articleForm.append("author", pollData.author);

        const articleRes = await fetch(`${API_BASE}/articles/`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          body: articleForm,
        });

        if (!articleRes.ok) {
          const errData = await articleRes.json();
          console.error("📛 Помилка створення статті для опитування:", errData);
          throw new Error("Не вдалося створити статтю для опитування");
        }

        const article = await articleRes.json();

        // 2️⃣ Створюємо Poll
        const pollRes = await fetch(`${API_BASE}/polls/`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            article: article.id,
            question: pollData.question,
            choices: pollData.options.map((text) => ({ text })),
            channel: pollData.channel || null,
          }),
        });

        if (!pollRes.ok) {
          const errData = await pollRes.json();
          console.error("📛 Помилка створення опитування:", errData);
          throw new Error("Не вдалося створити опитування");
        }

        return await pollRes.json();
      };

    default:
      throw new Error("Невідомий тип контенту");
  }
};
export class PollFactory {
  constructor(token) {
    this.token = token;
  }

  async create(data) {
    const body = {
      question: data.question,
      choices: data.options.map(text => ({ text })),
      channel: data.channel || null,
    };

    const res = await fetch("http://127.0.0.1:8000/api/polls/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.token}`,
      },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const error = await res.json();
      throw new Error(JSON.stringify(error));
    }

    return await res.json();
  }
}
